let state={route:'landing',fixture:'A',step:0,passUnlocked:false,scenario:'Actual package',scenarioEdited:false,revisionSaved:false,pricing:null,events:[],form:{timeValue:'25',stage:'Recruiter outreach'}};
// Research controls are intentionally available only to a moderator using ?research=1.
// This is study-control separation, not authentication or a security boundary.
const researchMode=new URLSearchParams(window.location.search).get('research')==='1';
const routes=['landing','context','baseline','settings','opportunity','free','pass','report','scenarios','revision','export','delete'];
const flow=['Context','Current job','Your settings','Opportunity'];
const $=s=>document.querySelector(s); const app=$('#app');
function f(){return fixtures[state.fixture]};function activeOutcome(){let base=f();if(state.scenario==='Actual package')return base;return {...base,...scenarioPresets[state.fixture][state.scenario]}};function money(v){return v==='Unknown'||v==='Cannot assess'||v==='Known subtotal only'||String(v).includes('$')?v:`$${v}`}
function log(event,detail={}){state.events.push({time:new Date().toISOString(),event,screen:state.route,...detail});renderLog()}
function renderLog(){const el=$('#eventLog');if(el)el.textContent=JSON.stringify(state.events,null,2)}
function nav(){const items=[['landing','Home'],['context','Start screen'],['free','Free result'],['report','Decision report'],['scenarios','Scenarios']];$('#mainNav').innerHTML=items.map(([r,n])=>`<button data-route="${r}" class="${state.route===r?'active':''}">${n}</button>`).join('')}
function go(route){state.route=route;log('screen_visited',{route});render();window.scrollTo(0,0)}
function badge(status){let c=status.includes('conflict')||status.includes('below')||status.includes('Cannot')?'bad':status.includes('unknown')||status.includes('uncertain')||status.includes('Could')?'warn':'blue';return `<span class="pill ${c}">${status}</span>`}
function provenance(name){return `<div class="provenance" data-provenance="${name}">${['Confirmed','Estimated','Unknown','Not applicable'].map((p,i)=>`<button type="button" class="chip ${i===0?'selected':''}" data-value="${p}">${p}</button>`).join('')}</div>`}
function field(label,id,placeholder,prov=true,help=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" placeholder="${placeholder}" />${help?`<p class="helper">${help}</p>`:''}${prov?provenance(id):''}</div>`}
function stepper(){return `<div class="stepper">${flow.map((x,i)=>`<span class="step ${state.step===i?'active':''}">${i+1}. ${x}</span>`).join('')}</div>`}
function page(title,copy,body){let note=['baseline','opportunity'].includes(state.route)?`<div class="notice warning persistent-note"><strong>Research prototype note</strong><br>Use fictional or rounded values; report outcomes are preset research fixtures. Entered compensation is not calculated into the displayed research outcome.</div>`:'';return `<section class="page-head"><div class="eyebrow">Preliminary screen</div><h2>${title}</h2><p>${copy}</p>${note}</section>${body}`}
function landing(){return `<section class="hero"><div><div class="eyebrow">A research prototype for one real opportunity</div><h1>Know what it would take to leave.</h1><p>Career Value Tracker helps you compare one opportunity with the job you already have—without reducing a career decision to a single score.</p><div class="inline-actions"><button class="primary-button" data-route="context">Try a preliminary screen</button><button class="secondary-button" data-route="delete">How your data is handled</button></div><p class="legal">Employer names are optional. Your information is not sold to employers. This is not financial, legal, or career advice and will never tell you to accept or reject a job.</p></div><aside class="card hero-card"><div class="eyebrow">The decision process</div><div class="metric"><strong>1. Capture what you have</strong><span>Compensation, costs, time, and conditions.</span></div><div class="metric"><strong>2. Set your threshold</strong><span>Define what would make a move worthwhile to you.</span></div><div class="metric"><strong>3. Test one opportunity</strong><span>Keep recurring value, one-time effects, conditions, and uncertainty separate.</span></div></aside></section><section class="grid three"><div class="card feature"><strong>Not a salary calculator</strong><p>It starts with your current job, not a generic market number.</p></div><div class="card feature"><strong>Unknown is allowed</strong><p>You can show what you know without pretending missing facts are zero.</p></div><div class="card feature"><strong>Math, not advice</strong><p>See what could close a gap without being told what to do.</p></div></section>`}
function context(){return page('Start with the opportunity you are considering.','We use this only to shape the level of detail in the screen. You can use a nickname instead of a company name.',`${stepper()}<div class="card"><div class="field-grid"><div class="field"><label>Are you currently employed?</label><select id="employed"><option>Yes</option><option>No</option></select></div><div class="field"><label>Where is this opportunity in the process?</label><select id="stage">${['Recruiter outreach','Interviewing','Verbal offer','Written offer','Negotiating'].map(x=>`<option ${x===state.form.stage?'selected':''}>${x}</option>`).join('')}</select></div>${field('Employer or role nickname (optional)','nickname','e.g., Operations Manager role',false)}${field('What feels hardest about this decision right now?','hardest','Optional note',false)}</div><div class="nav-actions"><button class="secondary-button" data-route="landing">Back</button><button class="primary-button" data-next="baseline">Continue</button></div></div>`)}
function baseline(){return page('What does your current job provide today?','Use rounded amounts if you prefer. Mark an item Unknown rather than entering $0 unless you know it does not apply.',`${stepper()}<div class="card"><div class="section"><div class="section-title"><h3>Compensation</h3><span class="helper">Annual gross amounts</span></div><div class="field-grid">${field('Base salary','currentSalary','$110,000')}${field('Expected annual bonus','currentBonus','$8,000','true','Expected—not the theoretical maximum.')}${field('Employer retirement contribution','currentRetirement','$5,000')}${field('Employer HSA / usable HRA contribution','currentHsa','$1,000')}</div></div><div class="section"><div class="section-title"><h3>Benefits and time</h3><span class="helper">Expected use, not just policy maximums</span></div><div class="field-grid">${field('Employee insurance premium','currentPremium','$4,800 annually')}${field('PTO days you expect to use','currentPto','18')}${field('Typical weekly work commitment','currentHours','45 hours','true','Exclude commuting. Include recurring after-hours work.')}${field('Office days each active week','currentOffice','2')}</div></div><div class="section"><div class="section-title"><h3>Commute and job-caused costs</h3><span class="helper">Only incremental costs caused by the job</span></div><div class="field-grid">${field('Round-trip commute','currentCommute','50 minutes')}${field('Annual job-caused costs','currentCosts','$1,800','true','Parking, incremental meals, dependent care, required tools, etc.')}</div></div><div class="nav-actions"><button class="secondary-button" data-route="context">Back</button><button class="primary-button" data-next="settings">Continue</button></div></div>`)}
function settings(){return page('Define what makes a move worthwhile for you.','These are personal preferences, not objective market values. They remain separate from the job’s direct economics.',`${stepper()}<div class="card"><div class="section"><h3>Required improvement</h3><div class="field-grid">${field('Minimum improvement percentage','minimumPercent','e.g., 10%','false')}${field('Minimum improvement dollars','minimumDollars','e.g., $12,000','false')}${field('Clearly compelling improvement (optional)','preferredDollars','e.g., $20,000','false')}<div class="field"><label><input id="timeToggle" type="checkbox" checked /> Include your own value of additional or saved time</label><input id="timeValue" value="${state.form.timeValue}" placeholder="$ per hour" /><p class="helper">This is displayed separately as your selected assumption.</p></div></div></div><div class="section"><h3>Hard conditions</h3><div class="field-grid">${field('Maximum office days each week','maxOffice','2','false')}${field('Maximum one-way commute','maxCommute','45 minutes','false')}${field('Minimum usable PTO','minPto','15 days','false')}${field('Maximum travel','maxTravel','10%','false')}${field('Relocation','relocation','Not permitted','false')}${field('Provider / access condition','provider','Optional; e.g., specialist must be in network','false')}<div class="field full"><label>Custom condition</label><input placeholder="e.g., planned leave must be honored" /></div></div></div><div class="notice">Hard conditions do not turn into dollars. A financially attractive opportunity can still conflict with a condition you set.</div><div class="nav-actions"><button class="secondary-button" data-route="baseline">Back</button><button class="primary-button" data-next="opportunity">Continue</button></div></div>`)}
function opportunity(){return page('Add what you know about the opportunity.','Early opportunities often have gaps. Use a range when you have one; we will not assume a midpoint.',`${stepper()}<div class="card"><div class="section"><h3>Compensation</h3><div class="field-grid">${field('Salary low','oppSalaryLow','$125,000')}${field('Salary high (optional)','oppSalaryHigh','$140,000')}${field('Target bonus / expected payout','oppBonus','15% target; 70–100% expected')}${field('Other recurring cash','oppOther','Optional')}</div></div><div class="section"><h3>Benefits</h3><div class="field-grid">${field('Employer retirement contribution','oppRetirement','Unknown')}${field('Employee insurance premium','oppPremium','$4,000–$8,000')}${field('Employer HSA / usable HRA','oppHsa','Optional')}${field('PTO expected to use','oppPto','15–20 days')}</div></div><div class="section"><h3>Time, location, and one-time terms</h3><div class="field-grid">${field('Weekly work commitment','oppHours','50–55 hours')}${field('Office days each active week','oppOffice','3–5')}${field('Round-trip commute','oppCommute','60–90 minutes')}${field('Sign-on payment','oppSignon',f().signon)}${field('Other job-caused costs','oppCosts','$3,000–$6,000')}${field('Transition losses you already know','transition','e.g., bonus forfeiture')}</div></div><div class="nav-actions"><button class="secondary-button" data-route="settings">Back</button><button class="primary-button" data-route="free">See preliminary screen</button></div></div>`)}
function free(){let x=f(), broad=x.free;return `<section class="result-hero"><div class="eyebrow">Your preliminary screen</div><h1>${broad}</h1><p>Based on the information currently available, this is a directional screen—not a final decision.</p><p class="helper">The full Decision Report shows your exact minimum target and, if you set one, your preferred target.</p><p class="notice warning"><strong>Preset research example</strong><br>This result tests the presentation experience. Your entered values did not calculate this fixture.</p></section><div class="grid two section"><div class="card"><h3>Known conditions</h3>${badge(x.conditions)}<p>${x.conditions}</p></div><div class="card"><h3>Biggest drivers so far</h3><ul class="list">${x.drivers.map(d=>`<li>${d}</li>`).join('')}</ul></div></div><div class="card section"><h3>Information to confirm next</h3><div class="grid two">${x.missing.map((m,i)=>`<div class="notice ${i===0?'warning':''}"><strong>${m}</strong><br><span class="helper">This could change the analysis.</span></div>`).join('')}</div></div><div class="card locked section"><div class="locked-content"><h2>Detailed Decision Report</h2><div class="grid three">${['Break-even floor','Recurring gap','First-year result'].map(t=>`<div class="metric"><span>${t}</span><strong>$•••••</strong></div>`).join('')}</div></div><div class="unlock-callout"><div><h2>Unlock the full Decision Pass</h2><p>See exact recurring ranges, break-even, your minimum and preferred targets, one-time make-whole, detailed conditions, sensitivity, scenarios, revisions, and a printable report for this one opportunity.</p><button class="primary-button" data-route="pass">See the $29 research offer</button></div></div></div>`}
function pass(){return `<section class="page-head"><div class="eyebrow">Research-mode offer</div><h2>Follow one opportunity through its decision process.</h2><p>Update the same analysis as salary, benefits, timing, and work details change. This prototype simulates a reservation; it does not process payment.</p></section><div class="grid two"><div class="card"><div class="price">$29</div><h3>Opportunity Decision Pass</h3><ul class="list"><li>Exact recurring ranges and target gap</li><li>One-time transition and make-whole view</li><li>Conditions, completeness, and sensitivity</li><li>Up to three alternative scenarios</li><li>Mock printable decision report</li></ul><p class="helper">Access is framed around this opportunity’s decision process; the prototype does not promise a fixed duration.</p></div><div class="card"><h3>Would you reserve this at $29?</h3><p>This is a research question only. No payment will be taken here.</p><div class="grid"><button class="primary-button" id="reserve29">I’d reserve this at $29</button><button class="secondary-button" id="decline29">Not at $29</button><button class="secondary-button" id="notNow">Not now</button></div></div></div>`}
function report(){let x=f();if(!state.passUnlocked)return `<div class="card"><h2>Your full report is part of the Decision Pass.</h2><p>For this prototype, use the research offer screen to simulate unlocking it.</p><button class="primary-button" data-route="pass">Go to research offer</button></div>`;return `<section class="result-hero"><div class="eyebrow">Paid Decision Report · Gross / pre-tax where applicable</div><h1>${x.headline}</h1><div class="result-row"><div class="result-stat"><span>Recurring opportunity value</span><strong>${x.range}</strong></div><div class="result-stat"><span>Minimum target</span><strong>${x.minimum}</strong></div><div class="result-stat"><span>One-time effects</span><strong>${x.makeWhole}</strong></div></div></section><div class="report-grid section"><div><div class="card report-section"><h2>Your opportunity at a glance</h2><p>${x.headline} ${badge(x.complete)} ${badge(x.sensitivity)}</p><p class="helper">No overall score. This report does not advise you to accept or reject an offer.</p></div><div class="card report-section"><h3>Recurring economics and your target</h3><table class="table"><tr><th>Measure</th><th>Value</th></tr><tr><td>Your current job’s recurring economic value</td><td>${x.current}</td></tr><tr><td>Direct recurring improvement</td><td>${x.direct}</td></tr><tr><td>Your time adjustment <span class="helper">(user-selected)</span></td><td>${x.time}</td></tr><tr><td>Break-even floor</td><td>${x.breakEven}</td></tr><tr><td>Minimum target</td><td>${x.minimum}</td></tr><tr><td>Preferred target</td><td>${x.preferred}</td></tr><tr><td><strong>Current target gap</strong></td><td><strong>${x.gap}</strong></td></tr></table></div><div class="card report-section"><h3>One-time transition and make-whole</h3><p>${badge(x.makeWhole)} A sign-on payment can cover transition losses, but it does not change whether the recurring package clears your target.</p><table class="table"><tr><th>Measure</th><th>Value</th></tr><tr><td>First 12-month value</td><td>${x.firstYear}</td></tr><tr><td>Sign-on / one-time offer</td><td>${x.signon}</td></tr><tr><td>Make-whole status</td><td>${x.makeWhole}</td></tr></table></div><div class="card report-section"><h3>What could change this result?</h3><ul class="list">${x.missing.map(m=>`<li>${m}</li>`).join('')}</ul><button class="secondary-button" data-route="scenarios">Test package scenarios</button></div></div><aside><div class="card report-section"><h3>Your conditions</h3>${badge(x.conditions)}<p>${x.conditions}</p><p class="helper">Conditions are separate from the financial calculation.</p></div><div class="card report-section"><h3>How complete is this analysis?</h3>${badge(x.complete)}<p>${x.complete==='Preliminary'?'Material facts are still unresolved.':x.complete==='Substantial'?'Useful for discussion, with important assumptions still visible.':'Sufficiently complete under the stated assumptions.'}</p></div><div class="card report-section"><h3>Assumptions</h3><p class="helper">All values are gross/pre-tax unless noted. Time adjustment reflects your selected personal value, not an employer-paid benefit.</p><button class="secondary-button" data-route="export">Preview export</button></div></aside></div>`}
function scenarios(){if(!state.passUnlocked)return `<div class="card"><h2>Scenario testing is part of the Decision Pass.</h2><p>Use the research offer screen to simulate unlocking the full report, including hypothetical package scenarios.</p><button class="primary-button" data-route="pass">Go to research offer</button></div>`;let x=activeOutcome(),tabs=['Actual package','Salary-focused','Flexibility-focused','Balanced package'],hyp=state.scenario!=='Actual package';return `<section class="page-head"><div class="eyebrow">Scenario solver</div><h2>Test what would mathematically close a gap.</h2><p>These are preset research outcomes for hypothetical package changes—not negotiation advice, employer predictions, or production calculations.</p></section><div class="card"><label for="targetChoice">Target to test</label><select id="targetChoice"><option>Minimum personal target</option><option>Break-even floor</option><option>Preferred personal target</option><option>Fully cover one-time make-whole</option><option>Recurring target and make-whole</option></select><div class="scenario-tabs">${tabs.map(t=>`<button data-scenario="${t}" class="${state.scenario===t?'active':''}">${t}</button>`).join('')}</div><p class="scenario-note">${hyp?'Hypothetical scenario — changed terms are not confirmed. The preset outcome below changes visibly when this scenario is selected.':'Current package (known and estimated inputs retained). Select a hypothetical scenario to test a preset alternative.'}</p><div class="field-grid section"><div class="field"><label><input type="checkbox" checked /> Base salary is adjustable</label><input id="scenarioSalary" value="${hyp?'$130,000':'$125,000'}" /></div><div class="field"><label><input type="checkbox" checked /> Office days are adjustable</label><input id="scenarioOffice" value="${state.scenario==='Flexibility-focused'?'2':'3'}" /></div><div class="field"><label><input type="checkbox" /> Bonus is adjustable</label><input value="10% target" /></div><div class="field"><label><input type="checkbox" checked /> PTO is adjustable</label><input value="${state.scenario==='Flexibility-focused'?'20':'15'} days" /></div><div class="field"><label><input type="checkbox" /> Weekly hours are adjustable</label><input value="45 hours" /></div><div class="field"><label><input type="checkbox" checked /> Sign-on is adjustable</label><input value="$15,000" /></div></div>${hyp?'<button class="primary-button" id="updateScenario">Apply preset hypothetical outcome</button>':'<p class="notice">Choose Salary-focused, Flexibility-focused, or Balanced package before applying a hypothetical outcome.</p>'}</div><div class="grid two section"><div class="card"><h3>Scenario state</h3><div class="summary-list"><div><strong>Economics</strong><br>${x.headline}</div><div><strong>Recurring value / gap</strong><br>${x.range} · ${x.gap}</div><div><strong>Make-whole</strong><br>${x.makeWhole}</div><div><strong>Conditions</strong><br>${x.conditions}</div><div><strong>Completeness</strong><br>${x.complete}</div></div></div><div class="card"><h3>What changed</h3><p>${hyp?`This fixture-aware preset changes the displayed outcome for ${state.scenario}. ${state.scenarioEdited?'The selected preset was applied and logged.':'Review the hypothetical outcome, then apply it to log the interaction.'}`:'No hypothetical changes selected. The actual-package result remains visible.'}</p><button class="secondary-button" data-route="revision">See a fixture-specific information revision</button></div></div>`}
function revision(){let r=revisionPresets[state.fixture];return `<section class="page-head"><div class="eyebrow">Simulated revision flow</div><h2>New information can change the analysis.</h2><p>This fixture-specific example simulates an employer or participant confirming details after an early conversation.</p></section><div class="card"><div class="change-row"><strong>Changed item</strong><strong>Earlier value</strong><strong>New value</strong><strong>Source / date</strong></div>${r.rows.map(row=>`<div class="change-row"><span>${row[0]}</span><span>${row[1]}</span><span>${row[2]}</span><span>${row[3]}</span></div>`).join('')}<div class="notice section"><strong>Fixture-specific result state</strong><br>${r.result}</div><div class="nav-actions"><button class="secondary-button" data-route="report">Back to report</button><button class="primary-button" id="saveRevision">Save simulated revision</button></div></div>`}
function exportView(){let x=f();return `<section class="page-head"><div class="eyebrow">Mock export</div><h2>Printable Decision Report preview</h2><p>This is a visual prototype only. No file is generated or sent.</p></section><article class="export-sheet"><header><div class="eyebrow">Career Value Tracker</div><h2>Opportunity Decision Report</h2><p>Prepared for one active opportunity · ${x.stage}</p></header><h3>${x.headline}</h3><p>Recurring opportunity value: <strong>${x.range}</strong> · Minimum target: <strong>${x.minimum}</strong></p><hr><h3>At a glance</h3><ul><li>One-time transition: ${x.makeWhole}</li><li>Conditions: ${x.conditions}</li><li>Completeness: ${x.complete}</li><li>Sensitivity: ${x.sensitivity}</li></ul><p class="footer-note">Gross/pre-tax where applicable. User-selected time assumptions are identified separately. This is a decision aid, not financial, legal, or career advice.</p></article><div class="inline-actions section"><button class="primary-button" id="simulateExport">Simulate export</button><button class="secondary-button" data-route="report">Back to report</button></div>`}
function deleteView(){return `<section class="page-head"><div class="eyebrow">Data controls</div><h2>Delete your local prototype data</h2><p>This prototype stores only local, in-browser interaction state for the research walkthrough. There is no account and no server.</p></section><div class="card"><h3>What deletion does here</h3><ul class="list"><li>Clears the local event log, intake/form state, pricing responses, selected fixture, scenario state, revision state, and current screen state.</li><li>Returns this prototype to its initial Home screen state.</li><li>Does not send anything to an employer or third party, and does not affect an external record.</li></ul><button class="quiet-button danger-button" id="deleteLocal">Delete local prototype data</button></div>`}
function render(){nav();let v={landing,context,baseline,settings,opportunity,free,pass,report,scenarios,revision,export:exportView,delete:deleteView}[state.route];app.innerHTML=v();app.focus();bind()}
function bind(){document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.route)));document.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>{state.step++;if($('#stage'))state.form.stage=$('#stage').value;go(b.dataset.next)}));document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{b.parentElement.querySelectorAll('.chip').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');log('provenance_selected',{field:b.parentElement.dataset.provenance,provenance:b.dataset.value});}));
 const reserve=$('#reserve29'); if(reserve)reserve.onclick=()=>{state.pricing='reserve';state.passUnlocked=true;log('pricing_action',{action:'reserve_29'});toast('Reservation intent recorded for this research prototype.');setTimeout(()=>go('report'),350)};
 const decline=$('#decline29');if(decline)decline.onclick=()=>pricingDecline();const now=$('#notNow');if(now)now.onclick=()=>{state.pricing='not_now';log('pricing_action',{action:'not_now'});go('free');toast('Response logged. Continue exploring the free result or return to opportunity details.');};
 document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{state.scenario=b.dataset.scenario;log('scenario_selected',{scenario:state.scenario});render()});const upd=$('#updateScenario');if(upd)upd.onclick=()=>{log('scenario_changed',{scenario:state.scenario});toast('Hypothetical scenario updated.');};const rev=$('#saveRevision');if(rev)rev.onclick=()=>{log('revision_saved');toast('Simulated revision saved.');};const exp=$('#simulateExport');if(exp)exp.onclick=()=>{log('export_preview_opened');toast('Export simulation opened — no file was created.');};const del=$('#deleteLocal');if(del)del.onclick=()=>{state.events=[];state.passUnlocked=false;state.pricing=null;log('delete_data_route_opened');toast('Local prototype data cleared.');renderLog();};}
function pricingDecline(){log('pricing_action',{action:'not_at_29'});document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="priceModal"><div class="modal"><div class="eyebrow">Research question</div><h2>What makes you hesitate at $29?</h2><textarea id="declineReason" placeholder="Tell us in your own words."></textarea><div class="nav-actions"><button class="secondary-button" id="closeModal">Cancel</button><button class="primary-button" id="reasonNext">Continue</button></div></div></div>`);$('#closeModal').onclick=()=>$('#priceModal').remove();$('#reasonNext').onclick=()=>{let reason=$('#declineReason').value;log('pricing_decline_reason',{reason});$('#priceModal .modal').innerHTML=`<div class="eyebrow">Research question</div><h2>Is there a price where this would become something you would seriously consider?</h2><p>We want your own answer before showing any comparison prices.</p><input id="lowerPrice" placeholder="Enter a price, or leave blank" /><div class="nav-actions"><button class="secondary-button" id="closeModal">Skip</button><button class="primary-button" id="lowerNext">Continue</button></div>`;$('#closeModal').onclick=()=>$('#priceModal').remove();$('#lowerNext').onclick=()=>{let price=$('#lowerPrice').value;log('unaided_lower_price',{price});$('#priceModal .modal').innerHTML=`<div class="eyebrow">Exploratory only</div><h2>How do these prices change your reaction, if at all?</h2><p>These are not discounted offers and no payment is processed.</p><div class="grid three"><button class="secondary-button" data-price="19">$19</button><button class="secondary-button" data-price="39">$39</button><button class="secondary-button" data-price="59">$59</button></div><div class="nav-actions"><span></span><button class="primary-button" id="finishPricing">Finish</button></div>`;document.querySelectorAll('[data-price]').forEach(b=>b.onclick=()=>{log('exploratory_price_reaction',{price:b.dataset.price});b.classList.add('selected')});$('#finishPricing').onclick=()=>{$('#priceModal').remove();toast('Pricing feedback recorded. Thank you.');};};};}
