function pricingDecline(){log('pricing_action',{action:'not_at_29'});document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="priceModal"><div class="modal"><div class="eyebrow">Research question</div><h2>What makes you hesitate at $29?</h2><textarea id="declineReason" placeholder="Tell us in your own words."></textarea><div class="nav-actions"><button class="secondary-button" id="closeModal">Cancel</button><button class="primary-button" id="reasonNext">Continue</button></div></div></div>`);$('#closeModal').onclick=()=>$('#priceModal').remove();$('#reasonNext').onclick=()=>{log('pricing_decline_reason',{reason:$('#declineReason').value});$('#priceModal .modal').innerHTML=`<div class="eyebrow">Research question</div><h2>Is there a price where this would become something you would seriously consider?</h2><p>We want your own answer before showing any comparison prices.</p><input id="lowerPrice" placeholder="Enter a price, or leave blank" /><div class="nav-actions"><button class="secondary-button" id="closeModal">Skip</button><button class="primary-button" id="lowerNext">Continue</button></div>`;$('#closeModal').onclick=()=>$('#priceModal').remove();$('#lowerNext').onclick=()=>{log('unaided_lower_price',{price:$('#lowerPrice').value});$('#priceModal .modal').innerHTML=`<div class="eyebrow">Exploratory only</div><h2>How would each price change your reaction?</h2><p>These are not discounted offers and no payment is processed. Select one reaction for each price.</p>${['19','39','59'].map(p=>`<div class="section"><strong>$${p}</strong><div class="inline-actions"><button class="secondary-button" data-price="${p}" data-reaction="would_seriously_consider">Would seriously consider</button><button class="secondary-button" data-price="${p}" data-reaction="no_change">No change</button><button class="secondary-button" data-price="${p}" data-reaction="less_likely">Less likely</button></div></div>`).join('')}<div class="nav-actions"><span></span><button class="primary-button" id="finishPricing">Finish</button></div>`;document.querySelectorAll('[data-reaction]').forEach(b=>b.onclick=()=>{document.querySelectorAll(`[data-price="${b.dataset.price}"]`).forEach(x=>x.classList.remove('selected'));b.classList.add('selected');log('exploratory_price_reaction',{price:b.dataset.price,reaction:b.dataset.reaction})});$('#finishPricing').onclick=()=>{$('#priceModal').remove();toast('Pricing feedback recorded. Thank you.');};};};}
function toast(msg){let e=$('#toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3200)}
