if(researchMode){researchToggle.hidden=false;researchToggle.onclick=()=>{researchPanel.hidden=!researchPanel.hidden};$('#closeResearch').onclick=()=>researchPanel.hidden=true;}
else{researchToggle.hidden=true;researchPanel.hidden=true;}
